sys_variable_value.value:
(function execute(inputs, outputs) {
var v = new x_casemgmt.CaseTransitionValidator();
var g = new GlideRecord('x_casemgmt_case');
var r;
if (g.get(String(inputs.case_sys_id))) {
var t = String(inputs.target_status);
if (t == 'Open') { r = v.canTransitionToOpen(g); }
else if (t == 'In Progress') { r = v.canTransitionToInProgress(g); }
else if (t == 'Resolved') { r = v.canTransitionToResolved(g); }
else if (t == 'Closed') { r = v.canTransitionToClosed(g, gs.getUserID()); }
else if (t == 'Pending') { r = { ok: true }; }
else { r = { ok: false, error: 'Unsupported target status.' }; }
} else {
r = { ok: false, error: 'Case record is missing.' };
}
outputs.blocked = r.ok ? 'false' : 'true';
outputs.error_message = r.ok ? '' : String(r.error);
})(inputs, outputs);

